<script setup>
import { computed, onMounted, ref } from 'vue'
import AppModal from '../../components/ui/AppModal.vue'
import AppIcon from '../../components/ui/AppIcon.vue'
import StatusBadge from '../../components/ui/StatusBadge.vue'
import { request, descargar, leerImagen } from '../../services/http'
const formatoFecha=valor=>new Date(/Z$|[+-]\d{2}:\d{2}$/.test(valor)?valor:valor+'Z').toLocaleString('es-EC',{timeZone:'America/Guayaquil'})
const props=defineProps({oficina:Boolean,vistaInicial:{type:String,default:'reservas'}})
const reservas=ref([]),pagos=ref([]),avisos=ref([]),error=ref(''),aviso=ref(''),ocupado=ref(false),cargando=ref(true),tab=ref(props.vistaInicial)
const busqueda=ref(''),filtroEstado=ref(''),pagina=ref(1),seleccion=ref(null),metodo=ref('TRANSFERENCIA'),referencia=ref(''),comprobante=ref(null),errorModal=ref('')
const pagoSeleccionado=ref(null),motivo=ref(''),respaldo=ref(false),vistaComprobante=ref(''),comprobanteAbierto=ref(false),cancelacion=ref(null)
const reservasPorId=computed(()=>new Map(reservas.value.map(r=>[r.reserva_id,r])))
const filtrados=computed(()=>reservas.value.filter(r=>(!filtroEstado.value||r.estado===filtroEstado.value)&&[r.reserva_id,r.pasajero_nombre,r.pasajero_cedula,r.origen,r.destino].some(v=>String(v??'').toLowerCase().includes(busqueda.value.toLowerCase()))))
const paginas=computed(()=>Math.max(1,Math.ceil(filtrados.value.length/8)))
const filas=computed(()=>filtrados.value.slice((Math.min(pagina.value,paginas.value)-1)*8,Math.min(pagina.value,paginas.value)*8))
const pendientes=computed(()=>pagos.value.filter(p=>p.estado==='PENDIENTE'))
const metricas=computed(()=>[['Reservas',reservas.value.length],['Por revisar',pendientes.value.length],['Boletos confirmados',reservas.value.filter(r=>r.estado==='CONFIRMADA').length],['Pendientes de pago',reservas.value.filter(r=>r.estado==='PENDIENTE').length]])
async function cargar(){cargando.value=true;error.value='';try{[reservas.value,pagos.value,avisos.value]=await Promise.all([request('/reservas/historial'),request('/pagos'),request('/notificaciones')])}catch(e){error.value=e.message}finally{cargando.value=false}}
onMounted(cargar)
async function ejecutar(fn,mensaje=''){if(ocupado.value)return;ocupado.value=true;error.value='';aviso.value='';try{await fn();if(mensaje)aviso.value=mensaje;await cargar()}catch(e){error.value=e.message}finally{ocupado.value=false}}
function abrirPago(r){seleccion.value=r;metodo.value='TRANSFERENCIA';referencia.value='';comprobante.value=null;errorModal.value=''}
async function registrar(){if(ocupado.value)return;ocupado.value=true;errorModal.value='';try{const imagen=metodo.value==='EFECTIVO'?null:await leerImagen(comprobante.value);await request('/pagos',{method:'POST',body:JSON.stringify({reserva_id:seleccion.value.reserva_id,metodo_pago:metodo.value,monto:seleccion.value.precio,referencia:referencia.value||null,comprobante:imagen})});seleccion.value=null;aviso.value='El pago quedó registrado para revisión.';await cargar()}catch(e){errorModal.value=e.message}finally{ocupado.value=false}}
function abrirRevision(p){pagoSeleccionado.value=p;respaldo.value=false;motivo.value='';vistaComprobante.value='';errorModal.value=''}
async function verComprobante(p){if(ocupado.value)return;ocupado.value=true;errorModal.value='';try{vistaComprobante.value=(await request(`/pagos/${p.id}/comprobante`)).comprobante}catch(e){errorModal.value=e.status===404?'Este pago en efectivo no tiene comprobante adjunto.':e.message}finally{ocupado.value=false}}
async function revisar(aprobar){if(ocupado.value)return;ocupado.value=true;errorModal.value='';try{await request(`/pagos/${pagoSeleccionado.value.id}/${aprobar?'aprobar':'rechazar'}`,{method:'POST',body:JSON.stringify(aprobar?{descuento_verificado:respaldo.value}:{motivo:motivo.value.trim()})});pagoSeleccionado.value=null;vistaComprobante.value='';aviso.value=aprobar?'Pago aprobado. El boleto ya está disponible.':'Pago rechazado. El pasajero puede volver a presentar el comprobante.';await cargar()}catch(e){errorModal.value=e.message}finally{ocupado.value=false}}
async function cancelar(){if(ocupado.value)return;ocupado.value=true;errorModal.value='';try{await request(`/reservas/${cancelacion.value.reserva_id}`,{method:'DELETE'});cancelacion.value=null;aviso.value='Reserva cancelada y asiento liberado.';await cargar()}catch(e){errorModal.value=e.message}finally{ocupado.value=false}}
</script>
<template><section :class="oficina?'':'page-container customer-purchases'">
<div v-if="!oficina" class="page-intro"><div><p class="eyebrow-label">Tu viaje, a mano</p><h1>Mis compras</h1><p class="intro-description">Consulta tus reservas, registra pagos y conserva tus boletos.</p></div><RouterLink class="btn-primary" to="/viajes">Comprar otro boleto<AppIcon name="arrow" :size="16"/></RouterLink></div>
<div v-if="aviso" class="alert success" role="status">{{ aviso }}</div><div v-if="error" class="alert error" role="alert">{{ error }}</div>
<div v-if="oficina&&!cargando" class="metric-grid"><article v-for="[titulo,valor] in metricas" :key="titulo" class="card metric-card"><span class="metric-label">{{ titulo }}</span><strong class="metric-value">{{ valor }}</strong></article></div>
<nav class="tabs" aria-label="Gestión de compras"><button class="tab" :aria-pressed="tab==='reservas'" @click="tab='reservas'">Reservas y boletos</button><button v-if="oficina" class="tab" :aria-pressed="tab==='pagos'" @click="tab='pagos'">Revisión de pagos <span class="tab-count">{{ pendientes.length }}</span></button><button class="tab" :aria-pressed="tab==='notificaciones'" @click="tab='notificaciones'">Notificaciones <span v-if="avisos.some(n=>!n.leida)" class="tab-count">{{ avisos.filter(n=>!n.leida).length }}</span></button></nav>
<div v-if="cargando" class="loading-state" role="status">Cargando reservas y pagos…</div>
<template v-else><template v-if="tab==='reservas'"><div class="toolbar"><div class="search-control"><AppIcon name="search" :size="17"/><input v-model="busqueda" class="control" :placeholder="oficina?'Buscar pasajero, cédula o reserva…':'Buscar reserva o destino…'" aria-label="Buscar reservas" @input="pagina=1"></div><div class="toolbar-controls"><select v-model="filtroEstado" class="control" aria-label="Estado de reserva" @change="pagina=1"><option value="">Todos los estados</option><option>PENDIENTE</option><option>PAGO_EN_REVISION</option><option>CONFIRMADA</option><option>CANCELADA</option><option>EXPIRADA</option></select><button class="icon-button" :disabled="ocupado" aria-label="Actualizar compras" @click="cargar"><AppIcon name="refresh"/></button></div></div>
<section class="card"><div v-if="!filtrados.length" class="empty-state"><AppIcon name="ticket" :size="32"/><h3>No hay reservas que mostrar</h3><p>{{ busqueda||filtroEstado?'Prueba con otro filtro.':'Tus próximas compras aparecerán aquí.' }}</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Reserva y pasajero</th><th>Viaje</th><th>Importe</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="r in filas" :key="r.reserva_id"><td><strong>#{{ r.reserva_id }} · {{ r.pasajero_nombre||'Pasajero' }}</strong><small>{{ r.pasajero_cedula }} · Asiento {{ r.asiento }}</small></td><td><strong>{{ r.origen }} → {{ r.destino }}</strong><small>{{ r.fecha_viaje }} · {{ r.hora_salida?.slice(0,5) }} · {{ r.cooperativa }}</small></td><td class="numeric">${{ r.precio.toFixed(2) }}<small>{{ r.tipo_pasajero.replaceAll('_',' ').toLowerCase() }}</small></td><td><StatusBadge :estado="r.estado"/></td><td><div class="table-actions"><template v-if="r.estado==='PENDIENTE'"><button class="btn-secondary" :disabled="ocupado" @click="abrirPago(r)">Registrar pago</button><button class="btn-quiet" :disabled="ocupado" @click="cancelacion=r;errorModal=''">Cancelar</button></template><template v-else-if="r.estado==='CONFIRMADA'"><button class="btn-secondary" :disabled="ocupado" @click="ejecutar(()=>descargar(`/boletos/${r.reserva_id}/descarga`,`boleto-${r.reserva_id}.html`))">Boleto</button><button class="btn-quiet" :disabled="ocupado" @click="ejecutar(()=>descargar(`/boletos/${r.reserva_id}/qr`,`qr-${r.reserva_id}.png`))">QR</button>
</template><span v-else class="small muted">{{ r.estado==='PAGO_EN_REVISION'?'Esperando revisión':'Sin acciones pendientes' }}</span></div></td></tr></tbody></table></div></section><div v-if="paginas>1" class="toolbar" style="margin-top:16px"><span class="small muted">Página {{ Math.min(pagina,paginas) }} de {{ paginas }}</span><div class="toolbar-controls"><button class="btn-secondary" :disabled="pagina<=1" @click="pagina--">Anterior</button><button class="btn-secondary" :disabled="pagina>=paginas" @click="pagina++">Siguiente</button></div></div>
</template>
<section v-else-if="tab==='pagos'&&oficina" class="card"><div class="card-heading"><div><h2>Pagos pendientes de revisión</h2><p>Revisa el movimiento bancario antes de aprobar el comprobante.</p></div><button class="icon-button" aria-label="Actualizar pagos" :disabled="ocupado" @click="cargar"><AppIcon name="refresh"/></button></div><div v-if="!pendientes.length" class="empty-state"><AppIcon name="check" :size="32"/><h3>La bandeja está al día</h3><p>No hay pagos pendientes de revisión.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Pago y pasajero</th><th>Reserva</th><th>Método</th><th>Importe</th><th></th></tr></thead><tbody><tr v-for="p in pendientes" :key="p.id"><td><strong>Pago #{{ p.id }}</strong><small>{{ reservasPorId.get(p.reserva_id)?.pasajero_nombre }}</small></td><td>#{{ p.reserva_id }}<small>{{ reservasPorId.get(p.reserva_id)?.origen }} → {{ reservasPorId.get(p.reserva_id)?.destino }}</small></td><td>{{ p.metodo_pago }}<small>{{ p.referencia||'Ventanilla' }}</small></td><td class="numeric">${{ p.monto.toFixed(2) }}</td><td><button class="btn-secondary" :disabled="ocupado" @click="abrirRevision(p)">Revisar pago</button></td></tr></tbody></table></div></section>
<section v-else class="card"><div class="card-heading"><h2>Actividad y notificaciones</h2><button class="icon-button" aria-label="Actualizar notificaciones" :disabled="ocupado" @click="cargar"><AppIcon name="refresh"/></button></div><div v-if="!avisos.length" class="empty-state"><h3>Sin novedades por ahora</h3><p>Aquí encontrarás los cambios de estado de tus operaciones.</p></div><article v-for="n in avisos" :key="n.id" class="notification-row"><span class="notification-dot" :class="{leida:n.leida}"></span><div><p>{{ n.mensaje }}</p><small>{{ formatoFecha(n.creado_en) }}</small></div><button v-if="!n.leida" class="btn-quiet" :disabled="ocupado" @click="ejecutar(()=>request(`/notificaciones/${n.id}/leer`,{method:'PATCH'}))">Marcar leída</button></article></section></template>
<AppModal :abierto="!!seleccion" titulo="Registrar pago" :descripcion="`Reserva #${seleccion?.reserva_id} · USD ${seleccion?.precio.toFixed(2)}`" :ocupado="ocupado" @cerrar="seleccion=null"><form @submit.prevent="registrar"><div v-if="errorModal" class="alert error" role="alert">{{ errorModal }}</div><div class="form-grid"><label class="form-field full-width">Medio de pago<select v-model="metodo" :disabled="ocupado"><option value="TRANSFERENCIA">Transferencia bancaria</option><option value="DEPOSITO">Depósito bancario</option><option v-if="oficina" value="EFECTIVO">Efectivo en ventanilla</option></select></label><template v-if="metodo!=='EFECTIVO'"><label class="form-field full-width">Referencia bancaria<input v-model.trim="referencia" required maxlength="100" :disabled="ocupado"></label><label class="form-field full-width">Comprobante<input type="file" accept="image/png,image/jpeg" required :disabled="ocupado" @change="comprobante=$event.target.files[0]"><small>PNG o JPEG, hasta 2 MB. Solo tú y el personal de revisión podrán consultarlo.</small></label></template><div class="form-actions full-width"><button class="btn-secondary" type="button" :disabled="ocupado" @click="seleccion=null">Volver</button><button class="btn-primary" :disabled="ocupado">{{ ocupado?'Enviando…':'Enviar para revisión' }}</button></div></div></form></AppModal>
<AppModal :abierto="!!pagoSeleccionado" :titulo="`Revisar pago #${pagoSeleccionado?.id}`" :ocupado="ocupado" ancho @cerrar="pagoSeleccionado=null"><template v-if="pagoSeleccionado"><div v-if="errorModal" class="alert error" role="alert">{{ errorModal }}</div><dl class="detail-list"><div><dt>Pasajero</dt><dd>{{ reservasPorId.get(pagoSeleccionado.reserva_id)?.pasajero_nombre }}</dd></div><div><dt>Reserva y cédula</dt><dd>#{{ pagoSeleccionado.reserva_id }} · {{ reservasPorId.get(pagoSeleccionado.reserva_id)?.pasajero_cedula }}</dd></div><div><dt>Tarifa</dt><dd>{{ reservasPorId.get(pagoSeleccionado.reserva_id)?.tipo_pasajero }}</dd></div><div><dt>Medio / referencia</dt><dd>{{ pagoSeleccionado.metodo_pago }} · {{ pagoSeleccionado.referencia||'Sin referencia' }}</dd></div><div class="total"><dt>Importe</dt><dd>${{ pagoSeleccionado.monto.toFixed(2) }}</dd></div></dl><div class="receipt-preview"><button v-if="!vistaComprobante" class="btn-secondary" :disabled="ocupado" @click="verComprobante(pagoSeleccionado)">Ver comprobante adjunto</button><img v-else :src="vistaComprobante" alt="Comprobante bancario del pago seleccionado"></div><label v-if="reservasPorId.get(pagoSeleccionado.reserva_id)?.tipo_pasajero!=='GENERAL'" class="check-label"><input v-model="respaldo" type="checkbox" :disabled="ocupado">Verifiqué la cédula y el respaldo de la tarifa preferencial de este pasajero.</label><label class="form-field" style="margin-top:20px">Motivo de rechazo<textarea v-model="motivo" maxlength="255" rows="2" :disabled="ocupado" placeholder="Completa este campo solo si necesitas rechazar el pago."></textarea></label><div class="form-actions" style="margin-top:20px"><button class="btn-danger" :disabled="ocupado||!motivo.trim()" @click="revisar(false)">Rechazar pago</button><button class="btn-primary" :disabled="ocupado||(reservasPorId.get(pagoSeleccionado.reserva_id)?.tipo_pasajero!=='GENERAL'&&!respaldo)" @click="revisar(true)">{{ ocupado?'Procesando…':'Aprobar y emitir boleto' }}</button></div></template></AppModal>
<AppModal :abierto="!!cancelacion" titulo="Cancelar reserva" :ocupado="ocupado" @cerrar="cancelacion=null"><p class="muted">Se cancelará la reserva #{{ cancelacion?.reserva_id }} y el asiento volverá a estar disponible.</p><p v-if="errorModal" class="alert error" role="alert">{{ errorModal }}</p><div class="form-actions"><button class="btn-secondary" :disabled="ocupado" @click="cancelacion=null">Conservar reserva</button><button class="btn-danger" :disabled="ocupado" @click="cancelar">Confirmar cancelación</button></div></AppModal>
</section></template>
<style scoped>.customer-purchases{padding-block:45px;max-width:1200px}.tab-count{display:inline-grid;place-items:center;min-width:17px;height:17px;border-radius:4px;padding:0 4px;margin-left:5px;background:var(--brand-soft);font-size:9px;color:var(--brand)}.notification-row{padding:20px 24px;display:flex;gap:14px;align-items:flex-start;border-bottom:1px solid var(--border)}.notification-row:last-child{border-bottom:0}.notification-row>div{flex:1}.notification-row p{font-size:12px;margin:0 0 6px}.notification-row small{color:var(--muted);font-size:10px}.notification-dot{width:7px;height:7px;flex-shrink:0;border-radius:50%;background:var(--brand);margin-top:6px}.notification-dot.leida{background:var(--border)}.receipt-preview{margin:24px 0;padding:16px;border:1px dashed var(--border);border-radius:6px;text-align:center;background:var(--surface-soft)}.receipt-preview img{max-width:100%;max-height:400px;object-fit:contain}@media(max-width:620px){.notification-row{flex-wrap:wrap}}</style>
